#!/usr/bin/env python3
import requests
from urllib.parse import quote_plus
from http.cookies import SimpleCookie

def main():

    url = 'http://crypto.chal.csaw.io:8000/login'
    session = requests.Session()

    # Get the login page to get cookies if needed (CSRF, etc)
    session.get(url)

    # Username containing '|admin|' in the middle
    username = 'test|admin|foo'
    data = {'username': username}

    r = session.post(url, data=data, allow_redirects=False)
    if 'set-cookie' in r.headers:
        set_cookie = r.headers['set-cookie']
        cookie = SimpleCookie()
        cookie.load(set_cookie)
        if 'auth' in cookie:
            print(cookie['auth'].value)
        else:
            print('No auth cookie found')
    else:
        # Sometimes, the cookie is set by the server via a redirect
        # So follow the redirect chain and collect cookies
        redirect = r.headers.get('Location')
        if redirect:
            final = session.get('http://crypto.chal.csaw.io:8000' + redirect, allow_redirects=False)
            cookies = session.cookies
            if 'auth' in cookies:
                print(cookies['auth'])
            else:
                print('No auth cookie via redirect')
        else:
            print('No set-cookie found and no redirect')

if __name__ == '__main__':
    main()

